    String solve(String s){
        int L=s.length();
        char last='+';
        int cnt=0;
        for (int i=0;i<L;i++){
            char  c=s.charAt(L-1-i);
            if (c!=last){
                last=c;
                cnt++;
            }
        }
        return ""+cnt;
    }


