                cant[i] = sc.nextInt();
            }
            int first = 0, second = 0, max = 0;
            for (int i = 1; i < N; i++) {
                if (cant[i - 1] > cant[i]) {
                    int dif = cant[i - 1] - cant[i];
                    first += dif;
                    max = Math.max(max, dif);
                }
            }
            for (int i = 1; i < N; i++) {
                second += Math.min(max, cant[i-1]);
            }

            System.out.println("Case #" + caze + ": " + first + " " + second);
        }
    }

