            int[] pan = new int[D];
            int max = 1;
            for (int i = 0; i < pan.length; i++) {
                pan[i] = sc.nextInt();
                max = Math.max(max, pan[i]);
            }
            int ans = max;
            for (int i = 1; i <= max; i++) {
                int val = i;
                for (int j = 0; j < pan.length; j++) {
                    val += (pan[j] - 1) / i;
                }
                ans = Math.min(ans, val);
            }

            System.out.println("Case #" + caze + ": " + ans);
        }
    }

