         a[i] = cin.nextLine().split("[ ]+");
       }
       Set<String> e = new HashSet<>();
       Set<String> f = new HashSet<>();
       for (String str : a[0])
         e.add(str);
       for (String str : a[1])
         f.add(str);

       Set<String> hehe = new HashSet<>();
       int ans = 0;
