         for (int mask = 0; mask < (1 << (n - 2)); mask++) {
           Set<String> ee = new HashSet<>();
           Set<String> ff = new HashSet<>();
           for (int i = 2; i < n; i++) {
             if ((mask & (1 << (i - 2))) == 0) {

