       X = cin.nextBigDecimal();
       R = new BigDecimal[n];
       C = new BigDecimal[n];
       for (int i = 0; i < n; i++) {
         R[i] = cin.nextBigDecimal();
         C[i] = cin.nextBigDecimal();
       }

       boolean ok = true;
       double ans = 1E300;

       if (n == 1) {
         if (X.equals(C[0]))
           ans = V.doubleValue() / R[0].doubleValue();
         else
           ok = false;
       } else {
         if (C[0].equals(C[1])) {
           if (C[0].equals(X)) {
             ans = V.doubleValue() / (C[0].add(C[1])).doubleValue();
