             int X = in.nextInt();
             int R = in.nextInt();
             int C = in.nextInt();
             boolean richard;
             if (X == 1) {
                 richard = false;
             } else if (X == 2) {
                 richard = (R*C % 2 != 0);
             } else if (X == 3) {
                 richard = (R*C % 3 != 0) || Math.min(R,C) == 1;
             } else if (X == 4) {
                 richard = (R*C % 4 != 0) || Math.min(R,C) <= 2;
             } else if (X == 5) {
                 richard = (R*C % 5 != 0) || Math.min(R,C) <= 3;
             } else if (X == 6) {
                 richard = (R*C % 6 != 0) || Math.min(R,C) <= 3;
             } else {
                 richard = true;
             }
             out.println("Case #"+(t+1)+": "+(richard ? "RICHARD" : "GABRIEL"));
         }

         out.close();
     }

