public class A {
    FastScanner in;
    PrintWriter out;

    int[] dx = new int[] { -1, 0, 0, 1 };
    int[] dy = new int[] { 0, -1, 1, 0 };
    String dir = "^<>v";

    void solve() {
        int tc = in.nextInt();
        for (int t = 0; t < tc; t++) {
            out.print("Case #" + (t + 1) + ": ");
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] a = new char[n][];
            for (int i = 0; i < n; i++) {
                a[i] = in.next().toCharArray();
            }
            int cost = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (a[i][j] == '.') {
                        continue;
                    }
                    int nowDir = dir.indexOf(a[i][j]);
                    boolean ok = false;
                    {
                        int ni = i, nj = j;
                        while (true) {
                            ni += dx[nowDir];
                            nj += dy[nowDir];
                            if (ni < 0 || ni >= n || nj < 0 || nj >= m) {
                                break;
                            }
                            if (a[ni][nj] != '.') {
                                ok = true;
                                break;
                            }
                        }
                    }
                    if (ok) {
                        continue;
                    }
                    cost++;
                    for (int d = 0; d < 4; d++) {
                        {
                            int ni = i, nj = j;
                            while (true) {
                                ni += dx[d];
                                nj += dy[d];
                                if (ni < 0 || ni >= n || nj < 0 || nj >= m) {
                                    break;
                                }
                                if (a[ni][nj] != '.') {
                                    ok = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (!ok) {
                        cost = Integer.MAX_VALUE / 2;
                    }
                }
            }
            out.println(cost >= Integer.MAX_VALUE / 2 ? "IMPOSSIBLE" : cost);
            System.err.println((t + 1) + "/" + tc + " done");
        }
    }

    void run() {
        try {
            in = new FastScanner(new File("A.in"));
            out = new PrintWriter(new File("A.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

