                        P[0]--;
                    } else if (P[1] > P[0]) {
                        System.out.print(" B");
                        P[1]--;
                    } else {
                        System.out.print(" AB");
                        P[0]--;
                        P[1]--;
                    }
                }
            } else {
                ArrayList<Party> parties = new ArrayList<Party>();
                for (int j = 0; j < P.length; j++) {
                    parties.add(new Party((char) ('A' + j), P[j]));
