 public class D {


    private static final String fileName = "results/con2015/con2015Q/"+D.class.getSimpleName().toLowerCase();
    private static final String inputFileName = fileName + ".in";
    private static final String outputFileName = fileName + ".out";
    private static InputReader in;
    private static OutputWriter out;

    static final String GABRIEL = "GABRIEL", RICHARD = "RICHARD";
    private void solve() {
        int X = in.readInt(),
            R = in.readInt(),
            C = in.readInt();
        out.printLine(isPossible(X, R, C)?GABRIEL:RICHARD);
    }

    public static boolean isPossible(int X, int R, int C){


        if(X >= 7) return false;

        if((R*C)%X != 0)return false; 

        if((X+1)/2 > Math.min(R, C))return false; 
        if((X+1) > (R+C))return false; 
        if(X > Math.max(R, C))return false; 
        if((R*C)==8 && X==4)return false; 
        return true;
    }

