                 ANS[cur++] = AA[c.idx];

                 if (c.count > 1) {
                     c.count--;
                     colors.add(c);
                 }
             }

             for (int i = 0; i < N; i++) {
                 if (ANS[i] == ANS[(N + i - 1) % N]) {
