    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int n;
        Tour[][] tour;
        public void readInput(final IOFast io) throws IOException {
            n = io.nextInt();
            tour = new Tour[n][2];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 2; j++) {
                    int e = io.nextInt() - 1;
                    int l = io.nextInt();
                    int d = io.nextInt();
                    tour[i][j] = new Tour(e, l, d);
                }
            }
        }

        @Override
        public void run() {
            out.println(dfs(0, 0));
        }

        int dfs(int v, int t) {
            if (!eulerTour()) {
                return Integer.MAX_VALUE;
            }
            int ans = Integer.MAX_VALUE;
            for (int i = 0; i < 2; i++) {
                final Tour to = tour[v][i];
                if (!to.vis) {
                    to.vis = true;
                    ans = Math.min(ans, dfs(to.e, to.arrive(t)));
                    to.vis = false;
                }
            }
            if (ans == Integer.MAX_VALUE && finished()) ans = t;
            return ans;
        }

        boolean finished() {
            for (int i = 0; i < 2*n; i++) {
                if (!tour[i/2][i%2].vis) {
                    return false;
                }
            }
            return true;
        }

        boolean eulerTour() {
            int[] deg = new int[n];
            for (int i = 0; i < 2*n; i++) {
                if (!tour[i/2][i%2].vis) {
                    deg[i/2]++;
                    deg[tour[i/2][i%2].e]++;
                }
            }
            int odd = 0;
            for (int i = 0; i < n; i++) odd += deg[i] % 2;
            return odd == 0 || odd == 2;
        }

        static class Tour {
            final int e, l, d;
            boolean vis;
            public Tour(int e, int l, int d) {
                this.e = e;
                this.l = l;
                this.d = d;
            }
            int arrive(int t) {
                if (t % 24 > l) {
                    t = (t + 23) / 24 * 24;
                }
                return t + (l - t % 24) + d;
            }
        }


