                    String swap = cura[k];
                    cura[k] = cura[k+1];
                    cura[k+1] = swap;
                    swap = curb[k];
                    curb[k] = curb[k+1];
                    curb[k+1] = swap;}
                    if(numcheats(cura,curb)>bestconflicts)
                    {
                        bestconflicts = numcheats(cura,curb);
                        bestnewa = cura.clone();
                        bestnewb = curb.clone();
                    }
                }
                sofara = bestnewa;
                sofarb = bestnewb;
            }

        System.out.println("Case #"+curcase+": "+numcheats(sofara,sofarb));     
        }

