    public static int numcheats(String[] a,String[] b)
    {
        HashSet<String> as = new HashSet<String>();
        HashSet<String> bs = new HashSet<String>();
        int ret = 0;
        for(int i=0;i<a.length;i++)
        {
            if((as.contains(a[i]))&&(bs.contains(b[i])))
            {
                ret++;
            }
            else
            {
                as.add(a[i]);bs.add(b[i]);
            }
        }
        return ret;

    }

 }
