        boolean found = false;
        for (int i : sig) {
            if (i > 0) found = true;
            if (i < 0) return null;
        }
        if (!found) return "";
        for (int d = 0 ; d <= 9 ; d++) {
            int[] ds = sig.clone();
            for (char c : NUM[d].toCharArray()) ds[c-'A']--;
            String s = compute(ds);
            if (s != null) return d + s;
        }
        return null;
