package c2015_r1_2;









 public class Z3_1 {

     private static class Point {
         int x,y;

         public Point(int x, int y) {
             this.x = x;
             this.y = y;
         }

         @Override
         public boolean equals(Object o) {
             if (this == o) return true;
             if (o == null || getClass() != o.getClass()) return false;

             Point point = (Point) o;

             if (x != point.x) return false;
             if (y != point.y) return false;

             return true;
         }

         @Override
         public int hashCode() {
             int result = x;
             result = 31 * result + y;
             return result;
         }

         @Override
         public String toString() {
             return "P{" +
                     "x=" + x +
                     ", y=" + y +
                     '}';
         }
     }

     private static int calcHappy(List<Point> points) {
         int res = 0;
         for (int i=0;i<points.size();i++) {
             for (int j=i+1;j<points.size();j++) {
                 if (i!=j) {
                     Point point = points.get(i);
                     Point t = points.get(j);
                     if (point.x==t.x && Math.abs(point.y-t.y)==1) {
                         res++;
                     }
                     if (point.y==t.y && Math.abs(point.x-t.x)==1) {
                         res++;
                     }

                 }
             }
         }
         return res;
     }

     public static void main(String[] args) throws Exception {
         FileWriter fw = new FileWriter("C:\\output.txt");
         BufferedWriter out = new BufferedWriter(fw);

         String pathname = "C:\\Users\\YC14rp1\\Downloads\\B-small-attempt3.in";


         Scanner scanner = new Scanner(new File(pathname));
         int tn = scanner.nextInt();
         scanner.nextLine();
         for (int ti = 1; ti <= tn; ti++) {
             int r = scanner.nextInt();
             int c = scanner.nextInt();
             int n = scanner.nextInt();
             int l = r*c;
             int min = Integer.MAX_VALUE;
             for (int mask=0;mask<2<<l;mask++) {
                 int cnt = 0;
                 List<Point> points = new ArrayList<Point>();
                 for (int i = 0; i < l; i++) {
                     if ((mask & 1 << i) != 0) {
                         cnt++;
                         int x = i % r;
                         int y = (i-x)/r;
                         points.add(new Point(x,y));
                     }
                 }
                 if (cnt==n) {
                     int hap = calcHappy(points);
                     if (hap<min) {
                         min = hap;
                     }
                 }
             }
             String s;
             if (min==Integer.MAX_VALUE) {
                 s = "Case #" + ti + ": NOT POSSIBLE";
             } else {
                 s = "Case #" + ti + ": "+min;
             }
             System.out.println(s);
             out.write(s);
             out.write("\n");
         }
         out.close();
     }

