class Main {
     private Scanner stdin = new Scanner(System.in);
     private java.util.logging.Logger logger = null;
     public static String loggerName = "MainLogger";


     private void init() {
    Arrays.fill(fR_Ret,-1);
    fR_Ret[1]=1;
    for (int i=2; i<fR_Ret.length; i++) {
        if (fR_Ret[i]==-1) {
        fR_Ret[i] = fR_Ret[i-1]+1;
        } else if (fR_Ret[i-1]+1 < fR_Ret[i]) {
        fR_Ret[i] = fR_Ret[i-1]+1;
        }

        long r1 = revNum(i);
        long r2 = revNum(r1);
        if (r1 < i && r2 == i) {
        if (fR_Ret[(int)r1]+1 < fR_Ret[i]) {
            fR_Ret[i] = fR_Ret[(int)r1]+1;
        }
        }
    }
     }


     private int input() {
    int ret=0;
    String com1;
    int T;

    if (stdin.hasNextInt()) {
        T = stdin.nextInt();
    } else {
        return ret;
    }
    for (int t1=0; t1<T; t1++) {
        long n;
        if (stdin.hasNextLong()) {
        n = stdin.nextLong();
        } else {
        return ret;
        }
        solve(n);
    }
    ret=0;
        return ret;
     }

     private long revNum(long x) {
    long ret=0;
    while (x>0) {
        ret *= 10;
        ret += x%10;
        x/=10;
    }
    return ret;
     }

     private long[] fR_Ret = new long[1000000+1];
     private long fR(long n) {
    long ret=0;
    if (n==1) {
        return 1;
    }
    if (fR_Ret[(int)n] != -1) {
        return fR_Ret[(int)n];
    }

    long min=n;
    long result1 = fR(n-1);
    if (result1+1<min) {
        min = result1+1;
    }
    long r1 = revNum(n);
    long r2 = revNum(r1);
    if (r2 == n && r1 < n) {
        long result2 = fR(r1);
        if (result2+1<min) {
        min = result2+1;
        }
    }
    fR_Ret[(int)n]=min;
    return min;
     }

     private long h(long n) {
    long ret=0;
    for (long i=1; i<n; ) {
        if (i%10==9) {
        long r1 = revNum(i);

        if (r1>i && r1<=n) {
            i=r1;
            ret++;
            continue;
        }
        }
        ret++;
        i++;
    }
    return ret;
     }
     private long g(long n) {
    long ret=0;
    while (n>0) {
        long r1 = revNum(n);
        long r2 = revNum(r1);
        if (r1<n && r2 == n) {
        n=r1;
        ret ++;
        } else {
        n--;
        ret ++;
        }
    }
    return ret;
     }

     private void solve(long n) {
    long ans = h(n);
    output(ans);
     }

