            }

            boolean[] used = new boolean[10];
            for(int time = 1; ; time++){
                for(final char ch : ((N * time) + "").toCharArray()){
                    used[Character.getNumericValue(ch)] = true;
                }

                boolean ok = true;
                for(int i = 0; i < used.length; i++){
                    if(!used[i]){
                        ok = false;
                        break;
                    }
                }

                if(ok){
                    System.out.printf("Case #%d: %s\n", tt, time * N);
                    break;
                }
            }
        }

        sc.close();
    }

