 class TaskD {
     public void solve(int testNumber, InputReader in, OutputWriter out) {
         out.print("Case #" + testNumber + ": ");
         int x = in.readInt();
         int rowCount = in.readInt();
         int columnCount = in.readInt();
         if (x == 1) {
             out.printLine("GABRIEL");
         } else if (x == 2) {
             if ((rowCount * columnCount) % 2 == 0) {
                 out.printLine("GABRIEL");
             } else {
                 out.printLine("RICHARD");
             }
         } else if (x == 3) {
             if (rowCount * columnCount >= 6 && (rowCount * columnCount) % 3 == 0) {
                 out.printLine("GABRIEL");
             } else {
                 out.printLine("RICHARD");
             }
         } else if (x == 4) {
             if (Math.max(rowCount, columnCount) < 4 || (rowCount * columnCount) == 4 || (rowCount * columnCount) == 8) {
                 out.printLine("RICHARD");
             } else {
                 out.printLine("GABRIEL");
             }
         }
     }
 }

