    public void solve() throws Exception {
        int n = iread(), m = iread();

        first = new Edge[n];
        Edge[] all = new Edge[m];
        for (int i = 0; i < m; i++) {
            all[i] = addEdge(iread() - 1, iread() - 1);
        }

        timer = 0;
        used = new boolean[n];
        tin = new int[n];
        fup = new int[n];
        found = false;

        balance = new int[n];
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                dfs(i, null);
            }
        }

        if (found) {
            out.write("IMPOSSIBLE");
            return;
        }

        for (int i = 0; i < n; i++) {
            if (balance[i] != 0) {
                System.out.println("WTF");
            }
        }

        for (int i = 0; i < m; i++) {
            out.write(all[i].flow + "");
            if (all[i].flow ==0) {
                System.out.println("WTF");
            }
            if (all[i].flow>n*n) {
                System.out.println("WTF");
            }
            if (i + 1 < m)
                out.write(" ");
        }
    }

    Edge addEdge(int x, int y) {
        Edge e1 = new Edge(x, y);
        Edge e2 = new Edge(y, x);
        e1.back = e2;
        e2.back = e1;
        return e1;
    }

    Edge[] first;

    class Edge {
        int from, to, flow;
        Edge back, next;

        public Edge(int from, int to) {
            this.from = from;
            this.to = to;
            next = first[from];
            first[from] = this;
        }
    }

    boolean[] used;
    int[] tin, fup;
    int timer;
    boolean found = false;
    int[] balance;

    void dfs(int v, Edge back) {
        used[v] = true;
        tin[v] = fup[v] = timer++;
        for (Edge e = first[v]; e != null; e = e.next) {
            int to = e.to;
            if (e == back)
                continue;
            if (used[to]) {
                if (e.flow == 0) {
                    e.flow = 1;
                    e.back.flow = -1;
                    balance[v]++;
                    balance[e.to]--;
                }

                fup[v] = Math.min(fup[v], tin[to]);
            } else {
                dfs(to, e.back);

                e.flow = balance[to];
                e.back.flow = -balance[to];
                balance[v] += balance[to];
                balance[to] = 0;

                fup[v] = Math.min(fup[v], fup[to]);
                if (fup[to] > tin[v]) {
                    found = true;
                }
            }
        }
    }

