package codeJam2015;






 public class RQP2 {
    String line;
    StringTokenizer inputParser;
    BufferedReader is;
    FileInputStream fstream;
    DataInputStream in;

    void openInput(String file)
    {


        try{
            fstream = new FileInputStream(file);
            in = new DataInputStream(fstream);
            is = new BufferedReader(new InputStreamReader(in));
        }catch(Exception e)
        {
            System.err.println(e);
        }

    }

    void readNextLine()
    {
        try {
            line = is.readLine();
            inputParser = new StringTokenizer(line, " ");

        } catch (IOException e) {
            System.err.println("Unexpected IO ERROR: " + e);
        }   

    }

    int NextInt()
    {
        String n = inputParser.nextToken();
        int val = Integer.parseInt(n);


        return val;
    }

    long NextLong()
    {
        String n = inputParser.nextToken();
        long val = Long.parseLong(n);


        return val;
    }

    String NextString()
    {
        String n = inputParser.nextToken();
        return n;
    }

    void closeInput()
    {
        try {
            is.close();
        } catch (IOException e) {
            System.err.println("Unexpected IO ERROR: " + e);
        }

    }

    public static void main(String [] argv)
    {
        new RQP2(argv[0]);
    }

    public RQP2(String inputFile)
    {
        openInput(inputFile);
        readNextLine();

        int TC = NextInt();


        for(int tt=0; tt<TC; tt++)
        {   
            String output=solve();
            System.out.println("Case #"+(tt+1)+": "+output);
        }
        closeInput();
    }

    private String solve() {

        readNextLine();
        int D = NextInt();
        int [] p = new int[D];
        readNextLine();
        int ret = 0;
        for(int i=0; i<D; i++)
        {
            p[i] = NextInt();
            ret = Math.max(ret, p[i]);
        }
        int MAX = ret;
        for(int x=1; x<=MAX; x++)
        {
            int r = x;
            for(int i=0; i<D; i++)
            {
                if(p[i]>x)
                    r += (p[i] - 1) / x;
            }
            ret = Math.min(ret, r);
        }

        return ""+ret;
    }

 }


