public class C {
    int n, s;
    int[] x, y, z, vx, vy, vz;
    double[][] dist;
    boolean[] mark;
    double jump;

    String solve() {
        dist = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dist[i][j] = Math.hypot(x[i] - x[j], Math.hypot(y[i] - y[j], z[i] - z[j]));
            }
        }
        double low = 0;
        double high = dist[0][1];
        while (low + 1e-5 < high) {
            jump = (low + high) * 0.5;
            mark = new boolean[n];
            dfs(0);
            if (mark[1]) {
                high = jump;
            } else {
                low = jump;
            }
        }
        return "" + high;
    }

    void dfs(int v) {
        if (mark[v]) {
            return;
        }
        mark[v] = true;
        for (int u = 0; u < n; u++) {
            if (dist[v][u] <= jump) {
                dfs(u);
            }
        }
    }

